// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * Names the execution regime a cost measurement was taken in, so evidence gathered while background structures are
 * still building can never tighten the confident steady-state posteriors. Posterior maps are keyed by this record —
 * regime isolation is structural, not a special case. {@code adjacencyEpoch} is the direct-adjacency store's publish
 * counter; {@code kernelReady} is whether no Janino kernel compiles are pending; {@code dataGeneration} advances on
 * store mutation. The single-regime constant {@link #STEADY} serves sources with no context (tests, synthetic sources).
 */
record LmdbNativeRegimeKey(Phase phase, long adjacencyEpoch, boolean kernelReady, long dataGeneration) {

	enum Phase {
		/** A background structure (adjacency view, index) is being built; measurements are wildly unrepresentative. */
		BUILDING,
		/** Structures exist but the engine is not settled (stalled apply, consolidation, cold kernels). */
		TRANSITIONAL_COLD,
		/** The steady state that dispatch decisions should learn from. */
		WARM_STABLE
	}

	static final LmdbNativeRegimeKey STEADY = new LmdbNativeRegimeKey(Phase.WARM_STABLE, 0L, true, 0L);

	@Override
	public String toString() {
		return phase + ":" + adjacencyEpoch + ":" + (kernelReady ? "K" : "k") + ":" + dataGeneration;
	}
}
